// ====================================================
// NODE 3: Kiểm tra login và chuẩn bị token
// ====================================================
const response = $input.first().json;

// Kiểm tra lỗi login
if (!response.Success) {
  throw new Error(
    `Login CUKCUK thất bại!\n` +
    `ErrorType: ${response.ErrorType}\n` +
    `ErrorMessage: ${response.ErrorMessage}\n\n` +
    `Các lỗi thường gặp:\n` +
    `- ErrorType 1: Domain/AppID/LoginTime bị null hoặc rỗng\n` +
    `- ErrorType 2: Domain không tồn tại\n` +
    `- ErrorType 3: AppID không tồn tại\n` +
    `- ErrorType 4: Chữ ký không hợp lệ hoặc đã hết hạn (> 5 phút)\n` +
    `- ErrorType 7: Kết nối CUKCUK đang bị ngắt`
  );
}

const d = response.Data;

// Tính khoảng thời gian lấy dữ liệu:
// lastSyncDate = đầu ngày hôm nay (00:00:00 UTC)
const today        = new Date();
const startOfDay   = new Date(today);
startOfDay.setUTCHours(0, 0, 0, 0);

return [{
  json: {
    accessToken:   d.AccessToken,
    companyCode:   d.CompanyCode,
    environment:   d.Environment,
    appId:         d.AppID,
    domain:        d.Domain,
    lastSyncDate:  startOfDay.toISOString(),   // ví dụ: 2026-03-30T00:00:00.000Z
    fetchDate:     today.toISOString()
  }
}];

// ====================================================
// NODE CUỐI: Ghi log kết quả thành công
// ====================================================
const items = $input.all();
const count = items.length;
const now   = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

console.log(`✅ [${now}] Đã ghi ${count} đơn hàng doanh thu vào Excel.`);

return [{
  json: {
    success:   true,
    message:   `Đã đồng bộ ${count} đơn hàng vào Excel`,
    timestamp: now,
    count:     count
  }
}];

// ====================================================
// NODE 5: Xử lý & làm phẳng dữ liệu Orders → doanh thu
// ====================================================
const response = $input.first().json;

if (!response.Success) {
  throw new Error(`Lấy orders thất bại! ErrorType: ${response.ErrorType} - ${response.ErrorMessage}`);
}

const orders = response.Data || [];

if (orders.length === 0) {
  console.log('Không có đơn hàng mới trong khoảng thời gian này.');
  return [{ json: { _noData: true, message: 'Không có đơn hàng mới', count: 0 } }];
}

// Bản đồ trạng thái đơn hàng
const statusMap = {
  0:  'Không xác định',
  1:  'Đang phục vụ',
  3:  'Yêu cầu thanh toán',
  4:  'Đã thanh toán',
  5:  'Đã hủy',
  6:  'Đặt trước',
  7:  'Chưa gửi bếp/bar',
  8:  'Chưa chế biến',
  9:  'Đang chờ giao hàng',
  10: 'Đang giao hàng',
  11: 'Đã giao hàng'
};

// Bản đồ loại đơn hàng
const typeMap = {
  1: 'Tại bàn',
  2: 'Mang về',
  3: 'Giao hàng'
};

// Format số tiền VND
const formatVND = (num) => (num || 0).toLocaleString('vi-VN');

// Format ngày giờ theo múi giờ Việt Nam
const formatDate = (dateStr) => {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
};

// Chuyển mỗi order thành 1 dòng Excel (chỉ lấy đơn ĐÃ THANH TOÁN — status = 4)
// Bỏ comment dòng filter bên dưới nếu bạn muốn lấy TẤT CẢ trạng thái:
const paidOrders = orders.filter(o => o.Status === 4); // ← chỉ đơn đã thanh toán
// const paidOrders = orders; // ← bỏ comment dòng này để lấy tất cả

if (paidOrders.length === 0) {
  return [{ json: { _noData: true, message: 'Không có đơn hàng đã thanh toán', count: 0 } }];
}

const rows = paidOrders.map(order => ({
  json: {
    'Ngày Giờ':          formatDate(order.Date),
    'Mã Đơn':            order.No        || '',
    'Loại Đơn':          typeMap[order.Type]   || `Loại ${order.Type}`,
    'Trạng Thái':        statusMap[order.Status] || `${order.Status}`,
    'Tên Khách Hàng':    order.CustomerName  || '',
    'SĐT Khách Hàng':   order.CustomerTel   || '',
    'Địa Chỉ Giao':     order.ShippingAddress || '',
    'Phí Giao Hàng':    order.DeliveryAmount || 0,
    'Tiền Đặt Trước':   order.DepositAmount  || 0,
    'Tổng Tiền (VND)':  order.TotalAmount    || 0,
    'ID Chi Nhánh':     order.BranchId       || '',
    'ID Đơn Hàng':      order.Id             || ''
  }
}));

return rows;

// Không có dữ liệu mới — bỏ qua, không ghi gì
const now = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });
console.log(`ℹ️ [${now}] Không có đơn hàng mới, bỏ qua.`);

return [{
  json: {
    success:   true,
    message:   'Không có đơn hàng mới trong chu kỳ này',
    timestamp: now,
    count:     0
  }
}];

const APP_ID = 'CUKCUKOpenPlatform';
const DOMAIN = '39beef';
const SECRETKEY = 'b3efb0189752a4357fa6c94143d490ac3f8d3e969b143ccb10862fb4b57dc02d'

// giờ UTC, format ISO không có milliseconds, có Z
const loginTime = new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');

// payload gốc để gửi lên login
const loginPayload = {
  Domain: DOMAIN,
  AppID: APP_ID,
  LoginTime: loginTime
};

// chuỗi dùng để ký: JSON minified
const message = JSON.stringify(loginPayload);

return [
  {
    json: {
      AppID: APP_ID,
      Domain: DOMAIN,
      secretkey: SECRETKEY,
      LoginTime: loginTime,
      Message: message
    }
  }
];

return [{
  json: {
    Domain: $('Tạo message').first().json.Domain,
    AppID: $('Tạo message').first().json.AppID,
    LoginTime: $('Tạo message').first().json.LoginTime,
    SignatureInfo: $json.Digest,
    _debugMessage: $('Tạo message').first().json.Message  // thêm dòng này
  }
}];
